-- Six original LexiLoop mini-cartoons: one additional lesson for each CEFR level.
insert into cartoon_lessons (slug,title,level,duration_seconds,description,cover_emoji,cover_color,scenes)
values
('milos-red-balloon','Milo’s Red Balloon','A1',96,'A gentle mini-cartoon about Milo sharing a red balloon in the park.','🎈','#ffe9e6','[{"position":1,"title":"A red balloon","subtitleEn":"Milo finds a red balloon in the park.","translation":"Майло находит красный воздушный шарик в парке.","illustration":"🎈","durationSeconds":32},{"position":2,"title":"It floats away","subtitleEn":"The balloon floats over the small pond.","translation":"Шарик плывёт по воздуху над маленьким прудом.","illustration":"🌤️","durationSeconds":32},{"position":3,"title":"A new friend","subtitleEn":"Milo shares the balloon with a new friend.","translation":"Майло делится шариком с новым другом.","illustration":"🤝","durationSeconds":32}]'::jsonb),
('the-forest-picnic','The Forest Picnic','A2',118,'A warm mini-cartoon about friends protecting their picnic from the rain.','🧺','#e9f4df','[{"position":1,"title":"Picnic time","subtitleEn":"Three friends carry a basket to the forest picnic.","translation":"Трое друзей несут корзину на пикник в лес.","illustration":"🧺","durationSeconds":39},{"position":2,"title":"Sudden rain","subtitleEn":"Suddenly, rain falls and the wind lifts their blanket.","translation":"Внезапно начинается дождь, и ветер поднимает их плед.","illustration":"🌧️","durationSeconds":39},{"position":3,"title":"A safe shelter","subtitleEn":"They find shelter under a wide old tree.","translation":"Они находят укрытие под широким старым деревом.","illustration":"🌳","durationSeconds":40}]'::jsonb),
('the-clockmakers-gift','The Clockmaker’s Gift','B1',142,'An original story about patience, repair, and a promise kept.','🕰️','#e8edff','[{"position":1,"title":"A broken clock","subtitleEn":"A young inventor brings a broken clock to the town clockmaker.","translation":"Юный изобретатель приносит сломанные часы городскому часовщику.","illustration":"🕰️","durationSeconds":47},{"position":2,"title":"Patient work","subtitleEn":"Together they patiently test each small part.","translation":"Вместе они терпеливо проверяют каждую маленькую деталь.","illustration":"🔧","durationSeconds":47},{"position":3,"title":"A bright solution","subtitleEn":"Their careful repair becomes a gift for the whole town.","translation":"Их аккуратный ремонт становится подарком для всего города.","illustration":"✨","durationSeconds":48}]'::jsonb),
('the-last-paper-boat','The Last Paper Boat','B2',156,'A thoughtful mini-cartoon about responsibility and a fragile river.','⛵','#e0f3f6','[{"position":1,"title":"A paper boat","subtitleEn":"A paper boat enters a strong current near the coastline.","translation":"Бумажный кораблик попадает в сильное течение у побережья.","illustration":"⛵","durationSeconds":52},{"position":2,"title":"A fragile journey","subtitleEn":"Its fragile shape makes the rescue difficult.","translation":"Его хрупкая форма делает спасение сложным.","illustration":"🌊","durationSeconds":52},{"position":3,"title":"Shared responsibility","subtitleEn":"The children learn that every river needs care and responsibility.","translation":"Дети понимают, что каждая река нуждается в заботе и ответственности.","illustration":"♻️","durationSeconds":52}]'::jsonb),
('the-city-beneath-the-rain','The City Beneath the Rain','C1',171,'A reflective mini-cartoon about anonymous kindness on a rainy evening.','☔','#eee8fb','[{"position":1,"title":"An evening pavement","subtitleEn":"On the wet pavement, Lina hesitates beneath a narrow doorway.","translation":"На мокром тротуаре Лина колеблется под узким дверным проёмом.","illustration":"☔","durationSeconds":57},{"position":2,"title":"A brief glimpse","subtitleEn":"She catches a glimpse of an anonymous note beside a lost umbrella.","translation":"Она замечает анонимную записку рядом с потерянным зонтом.","illustration":"📝","durationSeconds":57},{"position":3,"title":"Quiet persistence","subtitleEn":"Its quiet message gives her the persistence to continue home.","translation":"Его тихое послание даёт ей настойчивость продолжить путь домой.","illustration":"🏙️","durationSeconds":57}]'::jsonb),
('the-library-of-echoes','The Library of Echoes','C2',184,'An atmospheric mini-cartoon about language, memory, and a living labyrinth.','📚','#e3f2e6','[{"position":1,"title":"The labyrinth","subtitleEn":"A scholar enters a labyrinth where every shelf carries a resonance.","translation":"Учёный входит в лабиринт, где каждая полка несёт отголосок.","illustration":"📚","durationSeconds":61},{"position":2,"title":"A changing code","subtitleEn":"She tries to decipher an ephemeral code hidden between the books.","translation":"Она пытается расшифровать эфемерный код, скрытый между книгами.","illustration":"🔎","durationSeconds":61},{"position":3,"title":"The final paradox","subtitleEn":"The final paradox reveals that the library remembers its readers.","translation":"Последний парадокс раскрывает, что библиотека помнит своих читателей.","illustration":"🌀","durationSeconds":62}]'::jsonb)
on conflict (slug) do nothing;

insert into cartoon_lesson_words (lesson_id,word,phonetic,translation_ru,translation_kk,definition_en,example_sentence,difficulty,position)
select lesson.id,word.word,null,word.translation_ru,word.translation_kk,word.definition_en,word.example_sentence,lesson.level,word.position
from cartoon_lessons lesson
join (values
('milos-red-balloon','balloon','воздушный шарик','әуе шары','A light rubber bag filled with air or gas.','The balloon rose above the park.',1),('milos-red-balloon','red','красный','қызыл','Having the colour of blood or fire.','Milo holds a red balloon.',2),('milos-red-balloon','float','плыть по воздуху','қалқу','To move lightly through air or water.','The balloon can float high.',3),('milos-red-balloon','park','парк','саябақ','A public green space for people to enjoy.','They meet in the park.',4),('milos-red-balloon','share','делиться','бөлісу','To give part of something to another person.','Milo shares his balloon.',5),
('the-forest-picnic','picnic','пикник','серуен-пикник','A meal eaten outdoors.','They plan a forest picnic.',1),('the-forest-picnic','basket','корзина','себет','A container used to carry things.','The basket is full of fruit.',2),('the-forest-picnic','blanket','плед','жамылғы','A large piece of warm cloth.','The wind lifts the blanket.',3),('the-forest-picnic','suddenly','внезапно','кенеттен','Quickly and unexpectedly.','Suddenly, the rain begins.',4),('the-forest-picnic','shelter','укрытие','пана','A place that gives protection.','The tree gives them shelter.',5),
('the-clockmakers-gift','inventor','изобретатель','өнертапқыш','A person who creates a new device or idea.','The inventor brings a clock.',1),('the-clockmakers-gift','repair','ремонтировать','жөндеу','To fix something that is broken.','They repair the old clock.',2),('the-clockmakers-gift','patiently','терпеливо','шыдамдылықпен','In a calm way without becoming annoyed.','They work patiently together.',3),('the-clockmakers-gift','solution','решение','шешім','An answer to a problem.','The solution is simple and bright.',4),('the-clockmakers-gift','promise','обещание','уәде','A statement that you will do something.','She keeps her promise.',5),
('the-last-paper-boat','current','течение','ағыс','A continuous movement of water.','The current carries the boat.',1),('the-last-paper-boat','fragile','хрупкий','нәзік','Easily broken or damaged.','The paper boat is fragile.',2),('the-last-paper-boat','rescue','спасать','құтқару','To save someone or something from danger.','They rescue the boat.',3),('the-last-paper-boat','coastline','побережье','жағалау','The land along the edge of the sea.','Waves reach the coastline.',4),('the-last-paper-boat','responsibility','ответственность','жауапкершілік','A duty to care for something.','Clean water is our responsibility.',5),
('the-city-beneath-the-rain','hesitate','колебаться','кідіріп қалу','To pause before doing something.','Lina does not hesitate for long.',1),('the-city-beneath-the-rain','anonymous','анонимный','жасырын','With no name given.','An anonymous note waits nearby.',2),('the-city-beneath-the-rain','pavement','тротуар','тротуар','A hard path beside a road for walking.','Rain shines on the pavement.',3),('the-city-beneath-the-rain','glimpse','мельком увидеть','көз тастау','A quick or brief look.','She catches a glimpse of light.',4),('the-city-beneath-the-rain','persistence','настойчивость','табандылық','The quality of continuing despite difficulty.','Persistence helps her move on.',5),
('the-library-of-echoes','resonance','отголосок','жаңғырық','A deep, continuing quality of sound or meaning.','Every room has a different resonance.',1),('the-library-of-echoes','labyrinth','лабиринт','лабиринт','A complicated maze of paths.','The library is a labyrinth.',2),('the-library-of-echoes','decipher','расшифровать','шифрын ашу','To work out the meaning of something difficult.','She can decipher the code.',3),('the-library-of-echoes','ephemeral','эфемерный','қысқа ғұмырлы','Lasting for only a short time.','The symbols are ephemeral.',4),('the-library-of-echoes','paradox','парадокс','парадокс','A statement that seems contradictory but may be true.','The final clue is a paradox.',5)
) as word(lesson_slug,word,translation_ru,translation_kk,definition_en,example_sentence,position) on lesson.slug=word.lesson_slug
on conflict (lesson_id,word) do nothing;
